const r = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && git status --short && rg --files -g 'AGENTS.md' -g '!node_modules' -g '!vendor'","workdir":"/app","max_output_tokens":2000}),
  tools.exec_command({cmd:"ls -la .codex-role-output 2>/dev/null || true","workdir":"/app","max_output_tokens":1000}),
  tools.exec_command({cmd:"rg --files -g 'package.json' -g 'pnpm-lock.yaml' -g 'yarn.lock' -g 'Makefile' | head -80","workdir":"/app","max_output_tokens":2000})
]); r.forEach((x,i)=>text(JSON.stringify({i,result:x})));

const r=await Promise.allSettled([
  tools.exec_command({cmd:"find .. -name AGENTS.md -print","workdir":"/app","max_output_tokens":1000}),
  tools.exec_command({cmd:"git status --short; git rev-parse --show-toplevel; ls -la | head -60","workdir":"/app","max_output_tokens":3000}),
  tools.exec_command({cmd:"find . -maxdepth 3 -name package.json -o -name Makefile -o -name yarn.lock -o -name pnpm-lock.yaml | head -100","workdir":"/app","max_output_tokens":2000})
]); r.forEach((x,i)=>text(JSON.stringify({i,result:x})));

const r=await Promise.allSettled([
  tools.exec_command({cmd:"grep -R -n --include='*.ts' --include='*.js' 'providedOwnerEncSessionKey\\|_ownerEncSessionKey' src test packages --exclude-dir=node_modules | head -220","workdir":"/app","max_output_tokens":8500}),
  tools.exec_command({cmd:"grep -R -n --include='*.ts' 'loadMultiple\\|load(' src/api/entities src/api/worker 2>/dev/null | head -120","workdir":"/app","max_output_tokens":4500}),
  tools.exec_command({cmd:"cat package.json; cat .codex-role-output/checkpoint.md","workdir":"/app","max_output_tokens":5000})
]); r.forEach((x,i)=>text(JSON.stringify({i,result:x})));

